.chat-stage{
  display:flex;
  flex-direction:column;
  justify-content:flex-end;
  gap:var(--s-2);
  height:480px;
  padding:var(--s-6);
  background:var(--obsidian-900);
  border:var(--bw-1) solid var(--obsidian-800);
  border-radius:var(--r-lg);
  overflow:hidden;
  position:relative;
}
.chat-stage-head{
  position:absolute;
  top:0;
  left:0;
  right:0;
  display:flex;
  align-items:center;
  gap:var(--s-3);
  padding:var(--s-4) var(--s-6);
  border-bottom:var(--bw-1) solid var(--obsidian-800);
  background:linear-gradient(to bottom, var(--obsidian-900) 60%, transparent);
  z-index:2;
}
.chat-stage-head .chat-avatar{
  width:28px;
  height:28px;
  font-size:var(--t-micro);
}
.chat-stage-head-title{
  font-size:var(--t-small);
  font-weight:600;
  color:var(--obsidian-100);
  letter-spacing:var(--tr-snug);
}
.chat-stage-head-status{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-300);
  text-transform:uppercase;
  margin-left:auto;
  display:flex;
  align-items:center;
  gap:var(--s-2);
}
.chat-stage-head-status::before{
  content:"";
  width:6px;
  height:6px;
  border-radius:50%;
  background:var(--success);
  flex-shrink:0;
}
.chat-stage-scroll{
  display:flex;
  flex-direction:column;
  gap:var(--s-3);
  padding-top:var(--s-12);
  margin-top:auto;
}
.chat-day{
  display:flex;
  align-items:center;
  gap:var(--s-3);
  margin:var(--s-3) 0 var(--s-1);
}
.chat-day::before, .chat-day::after{
  content:"";
  flex:1;
  height:1px;
  background:var(--obsidian-800);
}
.chat-day-label{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-300);
  text-transform:uppercase;
}
.chat-msg{
  display:flex;
  align-items:flex-end;
  gap:var(--s-3);
  max-width:84%;
}
.chat-msg-bot{
  align-self:flex-start;
}
.chat-msg-own{
  align-self:flex-end;
  flex-direction:row-reverse;
}
.chat-avatar{
  width:32px;
  height:32px;
  border-radius:50%;
  flex-shrink:0;
  background:var(--obsidian-700);
  color:var(--obsidian-100);
  display:flex;
  align-items:center;
  justify-content:center;
  font-family:var(--font-mono);
  font-size:var(--t-caption);
  font-weight:600;
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
}
.chat-avatar-bot{
  background:var(--obsidian-800);
  color:var(--primary-400);
  border:var(--bw-1) solid var(--obsidian-700);
}
.chat-avatar-spacer{
  width:32px;
  height:32px;
  flex-shrink:0;
  visibility:hidden;
}
.chat-stack{
  display:flex;
  flex-direction:column;
  gap:var(--s-1);
  min-width:0;
}
.chat-msg-own .chat-stack{
  align-items:flex-end;
}
.chat-meta{
  display:flex;
  align-items:baseline;
  gap:var(--s-2);
  margin-bottom:var(--s-0-5);
  padding:0 var(--s-2);
}
.chat-meta-name{
  font-size:var(--t-caption);
  font-weight:600;
  color:var(--obsidian-200);
  letter-spacing:var(--tr-snug);
}
.chat-meta-time{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-300);
}
.chat-bubble{
  padding:var(--s-3) var(--s-4);
  border-radius:var(--r-lg);
  font-size:var(--t-body);
  line-height:var(--lh-normal);
  letter-spacing:var(--tr-snug);
  word-wrap:break-word;
  overflow-wrap:anywhere;
}
.chat-bubble-bot{
  background:var(--obsidian-800);
  color:var(--obsidian-100);
  border:var(--bw-1) solid var(--obsidian-700);
}
.chat-bubble-own{
  background:var(--primary-700);
  color:var(--obsidian-050);
}
.chat-sr-only{
  position:absolute;
  width:1px;
  height:1px;
  padding:0;
  margin:calc(-1 * var(--s-px));
  overflow:hidden;
  clip:rect(0,0,0,0);
  white-space:nowrap;
  border:0;
}
.chat-composer-attach:focus-visible, .chat-composer-send:focus-visible, .chat-demo-replay:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--focus-offset);
  box-shadow:var(--ring-halo);
}
.chat-status{
  display:flex;
  align-items:center;
  gap:var(--s-1);
  padding:0 var(--s-2);
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-300);
  text-transform:uppercase;
}
.chat-tick{
  display:inline-flex;
  align-items:center;
  color:var(--obsidian-400);
  transition:color var(--d-quick) var(--ease-standard);
}
.chat-tick svg{
  width:14px;
  height:14px;
  display:block;
}
.chat-status-label{
  margin-left:var(--s-0-5);
}
.chat-bubble-typing{
  padding:var(--s-3) var(--s-4);
  min-height:36px;
}
.chat-typing{
  display:inline-flex;
  align-items:center;
  gap:var(--s-1);
  height:14px;
}
.chat-dot{
  width:6px;
  height:6px;
  border-radius:50%;
  background:var(--obsidian-300);
  animation:chat-dot-wave var(--d-slow) var(--ease-standard) infinite;
  transform-origin:center;
  will-change:transform, opacity;
}
.chat-dot:nth-child(2){
  animation-delay:160ms;
}
.chat-dot:nth-child(3){
  animation-delay:320ms;
}
.chat-bubble-media{
  padding:0;
  overflow:hidden;
}
.chat-media{
  display:block;
  width:280px;
  max-width:100%;
  aspect-ratio:16 / 10;
  background:repeating-linear-gradient(135deg, var(--obsidian-700) 0 1px, transparent 1px 10px), var(--obsidian-800);
  position:relative;
}
.chat-media-tag{
  position:absolute;
  left:var(--s-3);
  top:var(--s-3);
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  padding:var(--s-1) var(--s-2);
  background:var(--surface-glass);
  backdrop-filter:blur(var(--blur-glass));
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-sm);
  color:var(--obsidian-200);
}
.chat-media-caption{
  padding:var(--s-3) var(--s-4);
  font-size:var(--t-small);
  color:var(--obsidian-300);
  border-top:var(--bw-1) solid var(--obsidian-700);
}
.chat-linkprev{
  display:grid;
  grid-template-columns:56px 1fr;
  gap:var(--s-3);
  padding:var(--s-3);
  margin-top:var(--s-2);
  background:var(--obsidian-850);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-md);
}
.chat-linkprev-thumb{
  width:56px;
  height:56px;
  border-radius:var(--r-sm);
  background:repeating-linear-gradient(135deg, var(--obsidian-700) 0 1px, transparent 1px 6px), var(--obsidian-800);
}
.chat-linkprev-body{
  display:flex;
  flex-direction:column;
  gap:var(--s-0-5);
  min-width:0;
}
.chat-linkprev-domain{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--primary-400);
}
.chat-linkprev-title{
  font-size:var(--t-small);
  font-weight:600;
  color:var(--obsidian-100);
  letter-spacing:var(--tr-snug);
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.chat-linkprev-desc{
  font-size:var(--t-micro);
  color:var(--obsidian-300);
  overflow:hidden;
  display:-webkit-box;
  -webkit-line-clamp:2;
  -webkit-box-orient:vertical;
}
.chat-bubble-voice{
  padding:var(--s-3) var(--s-4);
  min-width:220px;
}
.chat-voice{
  display:flex;
  align-items:center;
  gap:var(--s-3);
}
.chat-voice-play{
  width:28px;
  height:28px;
  border-radius:50%;
  background:var(--obsidian-700);
  display:flex;
  align-items:center;
  justify-content:center;
  flex-shrink:0;
  color:var(--obsidian-100);
}
.chat-bubble-own .chat-voice-play{
  background:var(--primary-800);
  color:var(--obsidian-100);
}
.chat-voice-play svg{
  width:12px;
  height:12px;
  display:block;
}
.chat-waveform{
  display:flex;
  align-items:center;
  gap:var(--s-0-5);
  flex:1;
  height:22px;
}
.chat-voice-time{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-300);
  text-transform:uppercase;
  flex-shrink:0;
}
.chat-bubble-own .chat-voice-time{
  color:color-mix(in srgb, var(--obsidian-100) calc(var(--tint-strong) * 100%), transparent);
}
.chat-msg .chat-bubble, .chat-msg .chat-status, .chat-msg .chat-avatar, .chat-msg .chat-meta{
  opacity:0;
  transform:scale(0.92);
  transition:opacity var(--d-base) var(--ease-standard), transform var(--d-base) var(--ease-spring);
}
.chat-msg-own .chat-bubble{
  transform-origin:bottom right;
}
.chat-msg-bot .chat-bubble{
  transform-origin:bottom left;
}
.chat-msg .chat-avatar, .chat-msg .chat-meta{
  transform:translateY(4px) scale(1);
}
.chat-msg.is-in .chat-bubble, .chat-msg.is-in .chat-status, .chat-msg.is-in .chat-avatar, .chat-msg.is-in .chat-meta{
  opacity:1;
  transform:none;
}
.chat-bubble-content{
  opacity:0;
  transform:translateY(3px);
  transition:opacity var(--d-quick) var(--ease-standard), transform var(--d-quick) var(--ease-standard);
}
.chat-msg.is-in .chat-bubble-content{
  opacity:1;
  transform:none;
  transition-delay:80ms;
}
.chat-composer{
  display:flex;
  align-items:flex-end;
  gap:var(--s-3);
  padding:var(--s-3);
  background:var(--obsidian-850);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-lg);
  transition:border-color var(--d-quick) var(--ease-standard), box-shadow var(--d-quick) var(--ease-standard);
}
.chat-composer:focus-within{
  border-color:var(--primary-500);
  box-shadow:var(--ring-field);
}
.chat-composer-attach, .chat-composer-send{
  width:36px;
  height:36px;
  flex-shrink:0;
  border-radius:50%;
  display:flex;
  align-items:center;
  justify-content:center;
  border:var(--bw-1) solid transparent;
  background:transparent;
  color:var(--obsidian-300);
  cursor:pointer;
  transition:background var(--d-quick) var(--ease-standard), color var(--d-quick) var(--ease-standard), border-color var(--d-quick) var(--ease-standard), transform var(--d-quick) var(--ease-standard);
}
.chat-composer-attach svg, .chat-composer-send svg{
  width:16px;
  height:16px;
  display:block;
}
.chat-composer-attach:hover{
  background:var(--obsidian-800);
  color:var(--obsidian-100);
}
.chat-composer-send{
  background:var(--obsidian-700);
  color:var(--obsidian-400);
}
.chat-composer-textarea{
  flex:1;
  min-height:36px;
  max-height:132px;
  resize:none;
  background:transparent;
  border:none;
  outline:none;
  color:var(--obsidian-100);
  font-family:var(--font-sans);
  font-size:var(--t-body);
  line-height:var(--lh-normal);
  letter-spacing:var(--tr-snug);
  padding:var(--s-2) var(--s-2);
}
.chat-composer-textarea::placeholder{
  color:var(--obsidian-300);
}
.chat-composer-hint{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-300);
  text-transform:uppercase;
  margin-top:var(--s-2);
  display:flex;
  align-items:center;
  gap:var(--s-2);
}
.chat-composer-hint kbd{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  padding:var(--s-0-5) var(--s-1);
  background:var(--obsidian-800);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-xs);
  color:var(--obsidian-200);
}
.chat-anatomy{
  display:grid;
  grid-template-columns:minmax(280px, 380px) 1fr;
  gap:var(--s-10);
  padding:var(--s-8);
  background:var(--obsidian-900);
  border:var(--bw-1) solid var(--obsidian-800);
  border-radius:var(--r-lg);
  align-items:center;
}
.chat-anatomy-canvas{
  display:flex;
  flex-direction:column;
  gap:var(--s-3);
  padding:var(--s-6) var(--s-4);
  background:var(--obsidian-950);
  border:var(--bw-1) solid var(--obsidian-800);
  border-radius:var(--r-md);
}
.chat-anatomy-canvas .chat-msg{
  opacity:1;
  max-width:100%;
}
.chat-anatomy-canvas .chat-msg .chat-bubble, .chat-anatomy-canvas .chat-msg .chat-avatar, .chat-anatomy-canvas .chat-msg .chat-status, .chat-anatomy-canvas .chat-msg .chat-meta, .chat-anatomy-canvas .chat-msg .chat-bubble-content{
  opacity:1;
  transform:none;
  transition:none;
}
.chat-anatomy-legend{
  display:grid;
  gap:var(--s-3);
}
.chat-anatomy-row{
  display:grid;
  grid-template-columns:28px 1fr auto;
  gap:var(--s-3);
  align-items:baseline;
  padding-bottom:var(--s-3);
  border-bottom:var(--bw-1) solid var(--obsidian-800);
}
.chat-anatomy-row:last-child{
  border-bottom:none;
  padding-bottom:0;
}
.chat-anatomy-num{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--primary-400);
  padding-top:var(--s-0-5);
}
.chat-anatomy-label{
  font-size:var(--t-small);
  color:var(--obsidian-100);
  font-weight:500;
}
.chat-anatomy-value{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-300);
  text-transform:uppercase;
}
.chat-demo{
  display:grid;
  gap:var(--s-4);
}
.chat-demo-head{
  display:flex;
  align-items:center;
  gap:var(--s-3);
}
.chat-demo-head-title{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-300);
  text-transform:uppercase;
}
.chat-demo-head-spacer{
  flex:1;
}
.chat-demo-replay{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  padding:var(--s-1) var(--s-3);
  background:transparent;
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-sm);
  color:var(--obsidian-200);
  cursor:pointer;
  display:inline-flex;
  align-items:center;
  gap:var(--s-1);
  transition:border-color var(--d-quick) var(--ease-standard), color var(--d-quick) var(--ease-standard);
}
.chat-demo-replay:hover{
  border-color:var(--primary-500);
  color:var(--primary-400);
}
.chat-demo-replay svg{
  width:var(--icon-xs);
  height:var(--icon-xs);
  display:block;
}
@media (prefers-reduced-motion: reduce){
  .chat-msg .chat-bubble, .chat-msg .chat-avatar, .chat-msg .chat-meta, .chat-msg .chat-bubble-content, .chat-composer, .chat-composer-attach, .chat-composer-send, .chat-tick{
    transition:none !important;
    transform:none !important;
    opacity:1 !important;
  }
  .chat-dot{
    animation:none !important;
    opacity:1 !important;
  }
}
@media (max-width: 720px){
  .chat-stage{
    height:420px;
    padding:var(--s-4);
  }
  .chat-msg{
    max-width:92%;
  }
  .chat-anatomy{
    grid-template-columns:1fr;
    gap:var(--s-6);
    padding:var(--s-5);
  }
  .chat-media{
    width:100%;
  }
  .chat-composer-attach, .chat-composer-send{
    width:44px;
    height:44px;
  }
}
